template <typename I1, typename I2, typename O>
O set_diff_core(I1 f1, I1 l1, I2 f2, I2 l2, O out) {
    // I1, I2: Input Iterators (Read)
    // O: Output Iterator (Write only)
    while (f1 != l1 && f2 != l2) {
        if (*f1 < *f2) {
            *out++ = *f1++; // Output Iterator: Assignment & Post-increment
        } else if (*f2 < *f1) {
            ++f2;
        } else {
            ++f1; ++f2;
        }
    }
    // Copy remaining elements from the first range
    while (f1 != l1) {
        *out++ = *f1++;
    }
    return out;
}
